using System;
class Program {
    static void Main(string[] args) {
        int carPrice = 3000; // Price of the car
        int clothesPrice = 100; // Price of the clothes
        int bookPrice = 20; // Price of the book
        Console.WriteLine("Total Cost: $" + CalculatePurchaseCost(carPrice, clothesPrice, bookPrice));
    }
    static decimal CalculatePurchaseCost(int carPrice, int clothesPrice, int bookPrice) {
        decimal totalCost = (decimal)(carPrice + clothesPrice + bookPrice);
        return Math.Round(totalCost, 2);
    }
